async function activateWithKeyboard(page, target) {
  for (let step = 0; step < 150; step++) {
    if (await target.evaluate((el) => el === document.activeElement)) { await page.keyboard.press('Enter'); return; }
    await page.keyboard.press('Tab');
  }
  throw new Error('Controle não alcançado com Tab no percurso esperado');
}
